from taf.sbts.oam.coam.admin.schemas.procedure.lte_ccm_uplink import LTECCMUplink


class LTECCMUplinkPrach(LTECCMUplink):
    def __init__(self, lncel_rdn, measurement_type, reporting_time_interval, reception_subframe,
                 exception_subframe, earfcn, prach_configuration_index, preamble_index, accepted_timing_error,
                 constant_offset, delay_pattern_single_step_duration, root_seq_index=None, prach_cs=None,
                 prach_hs_flag=None, phys_cell_id=None, tdd_frame_conf=None, tdd_spec_subf_conf=None):
        super(LTECCMUplinkPrach, self).__init__(lncel_rdn=lncel_rdn,
                                                measurement_type=measurement_type,
                                                reporting_time_interval=reporting_time_interval,
                                                reception_subframe=reception_subframe,
                                                exception_subframe=exception_subframe,
                                                earfcn=earfcn,
                                                root_seq_index=root_seq_index,
                                                prach_cs=prach_cs,
                                                prach_hs_flag=prach_hs_flag,
                                                phys_cell_id=phys_cell_id,
                                                tdd_frame_conf=tdd_frame_conf,
                                                tdd_spec_subf_conf=tdd_spec_subf_conf)

        self.prach_params = {"prachConfIndex": self.validate_param('prachConfIndex',
                                                                   prach_configuration_index,
                                                                   [0, 63]),
                             "preambleIndex": self.validate_param('preambleIndex',
                                                                  preamble_index,
                                                                  [0, 63]),
                             "acceptedTimingError": self.validate_param('acceptedTimingError',
                                                                        accepted_timing_error,
                                                                        [0, 999999]),
                             "constantOffset": self.validate_param('constantOffset',
                                                                   constant_offset,
                                                                   [0, 999999]),
                             "delayPatternSingleStepDuration": self.validate_param(
                                 'delayPatternSingleStepDuration',
                                 delay_pattern_single_step_duration,
                                 [0, 1000]),
                             }

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_prach_param(parameter):
            return response_dict['params']['prachParams'][parameter]

        lncel_rdn = response_dict['lncel_rDN']
        measurement_type = response_dict['params']['measurementType']
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        reception_subframe = response_dict['params']['receptionSubframe']
        exception_subframe = response_dict['params']['expectionSubframe']
        earfcn = response_dict['params']['earfcn']
        root_seq_index = response_dict['params']['rootSeqIndex'] if 'rootSeqIndex' in response_dict['params'] else None
        prach_cs = response_dict['params']['prachCS'] if 'prachCS' in response_dict['params'] else None
        prach_hs_flag = response_dict['params']['prachHsFlag'] if 'prachHsFlag' in response_dict['params'] else None
        phys_cell_id = response_dict['params']['physCellId'] if 'physCellId' in response_dict['params'] else None
        tdd_frame_conf = response_dict['params']['tddFrameConf'] if 'tddFrameConf' in response_dict['params'] else None
        tdd_spec_subf_conf = response_dict['params']['tddSpecSubfConf'] if 'tddSpecSubfConf' in response_dict[
            'params'] else None

        prach_params = {"prachConfIndex": _get_prach_param('prachConfIndex'),
                        "preambleIndex": _get_prach_param('preambleIndex'),
                        "acceptedTimingError": _get_prach_param('acceptedTimingError'),
                        "constantOffset": _get_prach_param('constantOffset'),
                        "delayPatternSingleStepDuration": _get_prach_param('delayPatternSingleStepDuration')}

        return cls(lncel_rdn=lncel_rdn,
                   measurement_type=measurement_type,
                   reporting_time_interval=reporting_time_interval,
                   reception_subframe=reception_subframe,
                   exception_subframe=exception_subframe,
                   earfcn=earfcn,
                   prach_configuration_index=prach_params["prachConfIndex"],
                   preamble_index=prach_params["preambleIndex"],
                   accepted_timing_error=prach_params["acceptedTimingError"],
                   constant_offset=prach_params["constantOffset"],
                   delay_pattern_single_step_duration=prach_params["delayPatternSingleStepDuration"],
                   root_seq_index=root_seq_index,
                   prach_cs=prach_cs,
                   prach_hs_flag=prach_hs_flag,
                   phys_cell_id=phys_cell_id,
                   tdd_frame_conf=tdd_frame_conf,
                   tdd_spec_subf_conf=tdd_spec_subf_conf)

    def as_dict(self):
        attributes = super(LTECCMUplinkPrach, self).as_dict()
        attributes['params']['prachParams'] = self.prach_params

        return attributes
